set -euo pipefail; python3 - <<'PY'
import json, pathlib, sqlite3
root=pathlib.Path('/workspace/omega_runtime')
for label,p in [('LEGACY',root/'state/omega.sqlite3'),('UNIFIED',root/'data/omega_unified.db')]:
 print('===',label,str(p),'===')
 if not p.exists(): print('MISSING'); continue
 con=sqlite3.connect(f'file:{p}?mode=ro',uri=True); con.row_factory=sqlite3.Row
 names=[r[0] for r in con.execute("select name from sqlite_master where type='table' order by name")]
 print('TABLES',json.dumps(names,separators=(',',':')))
 for t in names:
  try: n=con.execute(f'select count(*) from \"{t}\"').fetchone()[0]; print('COUNT',t,n)
  except Exception as e: print('COUNT_ERR',t,type(e).__name__)
 for t,col in [('task','state'),('effect','state'),('effect_intent','dispatch_state'),('relay_ledger','state')]:
  if t in names:
   try: rows=con.execute(f'select {col},count(*) from {t} group by {col} order by {col}').fetchall(); print('STATES',t,json.dumps([list(r) for r in rows],separators=(',',':')))
   except Exception as e: print('STATES_ERR',t,type(e).__name__)
 con.close()
for d in ['inbox','outbox','master_bridge/submitted','master_bridge/responses']:
 p=root/'state'/d; files=list(p.glob('*.json')) if p.exists() else []; print('FILES',d,len(files))
PY
